var CameraEvent = class _CameraEvent extends Event {
  /** @typedef {string} CameraEventTypeValue
   * Camera event type. See {@link CameraEvent.Type}
   */
  /**
   * Possible camera events.
   * @enum {Type}
   * @property {CameraEventTypeValue} ZOOM Camera zoom event.
   * @readonly
   */
  static Type = Object.freeze({
    ZOOM: "camera_zoom",
    ROTATE: "camera_rotate",
    REST: "camera_rest",
    SLEEP: "camera_sleep"
  });
  #zoom;
  #position;
  #azimuthAngle;
  #polarAngle;
  /**
   * @param {object} parameters Event parameters.
   * @param {CameraEventTypeValue} parameters.type Camera event type.
   * @param {number} parameters.zoom Current normalized zoom.
   * @param {Vector3} parameters.position Camera world position.
   * @param {number} parameters.azimuthAngle Camera azimuth angle in radians.
   * @param {number} parameters.polarAngle Camera polar angle in radians.
   */
  constructor(parameters = {}) {
    super(parameters.type);
    this.#zoom = parameters.zoom;
    this.#position = parameters.position;
    this.#azimuthAngle = parameters.azimuthAngle;
    this.#polarAngle = parameters.polarAngle;
  }
  /**
   * Returns the normalized zoom that was set when the event was triggered.
   * @returns {number}
   */
  get zoom() {
    return this.#zoom;
  }
  /**
   * Returns the position of the camera when the event was triggered.
   * @returns {Vector3}
   */
  get position() {
    return this.#position;
  }
  /**
   * Returns the azimuth angle of the camera when the event was triggered.
   * @returns {number}
   */
  get azimuthAngle() {
    return this.#azimuthAngle;
  }
  /**
   * Returns the azimuth angle of the camera when the event was triggered.
   * @returns {number}
   */
  get polarAngle() {
    return this.#polarAngle;
  }
  /**
   * Clones this event.
   * @returns {CameraEvent}
   */
  clone() {
    return new _CameraEvent({
      type: this.type,
      zoom: this.#zoom,
      position: this.position,
      azimuthAngle: this.azimuthAngle,
      polarAngle: this.polarAngle
    });
  }
};

