// src/utils/Debugger.js
var Flag = Object.freeze({
  VIEWPORT: 1 << 0,
  // 1
  CAMERA: 1 << 1,
  // 2
  TOOLS: 1 << 2,
  // 4
  MODEL: 1 << 3,
  // 8
  TIME: 1 << 4,
  // 16
  TYPES: 1 << 5,
  // 32
  LAPLACIAN: 1 << 6,
  // 64
  EXPORT: 1 << 7,
  // 128
  SHADER: 1 << 8,
  // 256
  PARAMETERS: 1 << 9,
  // 512
  VOLUME: 1 << 10,
  // 1024
  EDITOR_PREPROCESSING: 1 << 11
  // 2048
});
var simulator = Flag.TOOLS;
var viewer = Flag.MODEL | Flag.VIEWPORT | Flag.CAMERA;
var all = simulator | viewer | Flag.TIME | Flag.TYPES | Flag.LAPLACIAN | Flag.SHADER;
var Level = Object.freeze({
  NONE: 0,
  VIEWER: viewer,
  SIMULATOR: simulator,
  ALL: all
});
var DebuggerSingleton = class extends EventTarget {
  #level = Level.NONE;
  #onLevelChange = new DebuggerEvent({ type: DebuggerEvent.Type.LEVEL_CHANGE });
  /**
   * Executes a parameter function if the debug level includes the parameter flag or level. Otherwise, does nothing.
   * @param {FlagValue} flag Desired debug flag or level.
   * @param {Function} fn Function to execute.
   */
  debug(flag = Level.NONE, fn) {
    if (this.includes(flag))
      fn();
  }
  /**
   * Sets a parameter debug level.
   * Throws an event when done.
   * @param {FlagValue} flag Debug flag or level to be set.
   */
  set(flag = Level.NONE) {
    this.#level = flag;
    this.dispatchEvent(this.#onLevelChange);
  }
  /**
   * Add a parameter flag to the current the debug level.
   * @param {FlagValue} flag Debug flag or level to add.
   */
  add(flag) {
    this.#level |= flag;
    this.dispatchEvent(this.#onLevelChange);
  }
  /**
   * Remove a parameter flag from the current debug level.
   * @param {FlagValue} flag Debug flag or level to remove.
   */
  remove(flag) {
    this.#level &= ~flag;
    this.dispatchEvent(this.#onLevelChange);
  }
  /**
   * Check if the current debug level includes the parameter level.
   * @param {FlagValue} flag Debug flag or level to check.
   * @returns {boolean} Returns true if the parameter level is included. False otherwise.
   */
  includes(flag) {
    return !!(this.#level & flag);
  }
  /**
   * Function to handle all possible errors.
   * @param {Error} error
   */
  handle(error) {
    this.debug(Level.ALL, () => {
      throw new Error(error.stack);
    });
    throw new Error(error.message);
  }
};
var Debugger = Object.freeze(new DebuggerSingleton());

