function resolveSettledPromise(result, message) {
  if (result.status === "rejected") {
    throw new TypeError(`${message}: ${result.reason}`);
  }
  return result.value;
}
function type(value) {
  if (value === null) {
    return "null";
  }
  const baseType = typeof value;
  if (!["object", "function"].includes(baseType)) {
    return baseType;
  }
  const tag2 = value[Symbol.toStringTag];
  if (typeof tag2 === "string") {
    return tag2;
  }
  if (baseType === "function" && Function.prototype.toString.call(value).startsWith("class")) {
    return "class";
  }
  const className = value.constructor.name;
  if (typeof className === "string" && className !== "") {
    return className;
  }
  return baseType;
}
function checkTypes(args, types) {
  Debugger.debug(Flag.TYPES, () => {
    args = [].slice.call(args);
    for (let i = 0; i < types.length; ++i) {
      const actualType = type(args[i]);
      const expectedType = types[i];
      if (type(expectedType) === "string") {
        if (actualType.toLowerCase() !== expectedType.toLowerCase()) {
          throw new TypeError('"' + actualType + '" is not a "' + expectedType + '"');
        }
        if (actualType === "number" && isNaN(args[i])) {
          throw new TypeError('"' + actualType + '" is a NaN');
        }
      } else {
        if (!(args[i] instanceof expectedType)) {
          throw new TypeError('"' + actualType + '" is not a "' + expectedType.name + '"');
        }
      }
    }
  });
}

