var body_mark_default2 = "varying vec3 projectedPosition;varying vec3 projectedCenter;void main(){vec3 sphere=position;vec3 center=vec3(0.0);vec3 modelSpaceCamera=(inverse(modelMatrix)*vec4(cameraPosition,1.0)).xyz;vec3 planeNormal=normalize(modelSpaceCamera-center);float denominator=length(planeNormal)*length(planeNormal);float scalar=dot(planeNormal,sphere)/denominator;projectedCenter=center;projectedPosition=sphere-planeNormal*scalar;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}";

// src/materials/BodyMarkMaterial.js
var BodyMarkMaterial = class {
  #material;
  /**
   * Body mark material constructor.
   * @param {number} radius Inner color radius in the [0, 1] range.
   * @param {Color} innerColor Inner body mark color.
   * @param {Color} outerColor Outer body mark color.
   */
  constructor(radius, innerColor, outerColor) {
    const uniforms = {
      radius: {
        value: radius
      },
      innerColor: {
        value: innerColor
      },
      outerColor: {
        value: outerColor
      },
      opacity: {
        value: 1
      }
    };
    this.#material = new ShaderMaterial(
      {
        uniforms,
        vertexShader: body_mark_default2,
        fragmentShader: body_mark_default,
        transparent: true,
        depthTest: false
      }
    );
  }
  /**
   * Returns the underlying threejs material instance.
   * @returns {Material}
   */
  get material() {
    return this.#material;
  }
  /**
   * Returns the inner color.
   * @returns {Color}
   */
  get innerColor() {
    return this.#material.uniforms.innerColor.value;
  }
  /**
   * Returns the outer color.
   * @returns {Color}
   */
  get outerColor() {
    return this.#material.uniforms.outerColor.value;
  }
  /**
   * Returns the opacity.
   * @returns {number}
   */
  get opacity() {
    return this.#material.uniforms.opacity.value;
  }
  /**
   * Sets the opacity.
   * @param {number} value The opacity [0,1]
   */
  set opacity(value) {
    this.#material.uniforms.opacity.value = value;
  }
  /**
   * Disposes the material.
   */
  dispose() {
    this.#material.dispose();
    this.#material = void 0;
  }
};

