var skin_unwrap_default = "#if !defined(UV)\n#define UV true\nvarying vec2 uvc;varying vec2 uv1c;\n#endif\nattribute vec2 uv1;attribute float textureIndex;\n#if defined(SIMULATION_TYPE_FULL_BODY)\nflat varying int vTextureIndex;\n#endif\nvoid main(){\n#if defined(SIMULATION_TYPE_FULL_BODY)\nvTextureIndex=int(textureIndex);\n#endif\nuvc=uv;uv1c=uv1;float z=2.*uv1.x*(uv1.x-1.)+.5;gl_Position=vec4(uv1.x-.5,uv1.y-.5,z,.5);}";

// src/materials/SkinBakeMaterial.js
var SkinBakeMaterial = class {
  // attributes
  /** @type {ShaderMaterial} */
  #material = null;
  /**
   * Creates a {@link SkinBakeMaterial}.
   * @param {SkinMaterial} skinMaterial Skin material to create from.
   */
  constructor(skinMaterial) {
    const uniforms = {
      map: {
        value: skinMaterial.map
      },
      areolaSkinBlurredMap: {
        value: skinMaterial.areolaSkinBlurredMap
      },
      areolaMaskMap: {
        value: skinMaterial.areolaMaskMap
      },
      cleanMap: {
        value: skinMaterial.originalCleanMap
        // use clean map without sharpen
      },
      minPredefinedRegionColor: {
        value: MIN_REGION_COLOR
      },
      predefinedRegionCount: {
        value: PREDEFINED_REGION_COUNT
      },
      inversePredefinedRegionStep: {
        value: PREDEFINED_REGION_INVERSE_COLOR_STEP
      },
      predefinedRegionCleaning: {
        value: skinMaterial.predefinedRegionCleaning.map((cleaning) => clone4(cleaning))
      },
      predefinedRegionMaskMap: {
        value: skinMaterial.predefinedRegionMaskMap
      },
      customRegionsMap: {
        value: skinMaterial.originalCustomRegionsMap
        // use custom region without sharpen
      },
      // skin imperfections
      skinImperfectionsCleanMask: new Uniform(skinMaterial.skinImperfectionsCleanMask),
      skinImperfectionsVisualMask: new Uniform(skinMaterial.skinImperfectionsVisualMask),
      skinImperfections: new Uniform([...skinMaterial.skinImperfections]),
      skinImperfectionsContext: new Uniform(clone4(skinMaterial.skinImperfectionsContext)),
      lipHydrationMap: {
        value: skinMaterial.lipHydrationMap
      },
      // blepharoplasty
      blepharoplastyMap: new Uniform(skinMaterial.blepharoplastyMap),
      blepharoplastyIntensity: new Uniform(skinMaterial.blepharoplastyIntensity)
    };
    this.#material = new ShaderMaterial({
      uniforms,
      vertexShader: skin_unwrap_default,
      fragmentShader: skin_bake_default
    });
    this.#material.defines[SHADER_MODEL_TYPE[SimulationType.BREAST]] = skinMaterial.simulationType === SimulationType.BREAST;
    this.#material.defines[SHADER_MODEL_TYPE[SimulationType.FACE]] = skinMaterial.simulationType === SimulationType.FACE;
    this.#material.defines[SHADER_MODEL_TYPE[SimulationType.FULL_BODY]] = skinMaterial.simulationType === SimulationType.FULL_BODY;
  }
  /**
   * Returns the underlying threejs material instance.
   * @returns {Material}
   */
  get material() {
    return this.#material;
  }
  /**
   * Disposes the material.
   */
  dispose() {
    this.material.dispose();
    this.#material = null;
  }
};

