function gradient(colors, alpha, color) {
  const length = colors.length;
  const i = alpha * (length - 1);
  const first = Math.floor(i);
  const second = (first + 1) % length;
  const t2 = i % 1;
  return color.lerpColors(colors[first], colors[second], t2);
}
