// src/utils/WireframeMesh.js
var WireframeMesh = class extends Mesh {
  // attributes
  /** @type {BufferGeometry} */
  #raycastGeometry = null;
  /**
   * Creates a {@link WireframeMesh}.
   * @param {object} parameters Constructor parameters.
   * @param {BufferGeometry} parameters.renderGeometry Wireframe geometry to display.
   * @param {BufferGeometry} parameters.raycastGeometry Wireframe geometry to raycast against.
   * @param {Material} parameters.material Target material.
   */
  constructor(parameters = {}) {
    checkTypes([parameters.renderGeometry, parameters.raycastGeometry, parameters.material], [BufferGeometry, BufferGeometry, Material]);
    super(parameters.renderGeometry, parameters.material);
    this.#raycastGeometry = parameters.raycastGeometry;
  }
  /**
   * Returns the geometry used for raycasting.
   * @returns {BufferGeometry}
   */
  get raycastGeometry() {
    return this.#raycastGeometry;
  }
  /**
   * Updates the geometry used for raycasting.
   * @param {BufferGeometry} value
   */
  set raycastGeometry(value) {
    this.#raycastGeometry = value;
  }
  /**
   * @inheritdoc
   * @type {Mesh['raycast']}
   */
  raycast(raycaster2, intersects) {
    const originalGeometry = this.geometry;
    this.geometry = this.#raycastGeometry;
    super.raycast(raycaster2, intersects);
    this.geometry = originalGeometry;
  }
};

