          pixels[(start + delta) * PIXEL_STRIDE + 1] = MAX_INTENSITY_COLOR;
          pixels[(start + delta) * PIXEL_STRIDE + 2] = MAX_INTENSITY_COLOR;
          pixels[(start + delta) * PIXEL_STRIDE + 3] = MAX_INTENSITY_COLOR;
