  const visual = {
    version: "1.0",
    width: texture.image.width,
    height: texture.image.height,
    [Object.values(SkinImperfectionType)[0].description.toUpperCase()]: [rle]
    // any skin imperfection wrinkle will do
  };
  const clean = {
    version: "1.0",
    width: texture.image.width,
    height: texture.image.height
    // nothing to clean
  };
