var STENCIL_REF = 1;
function createStencilMask(scene, geometry, position2, size2) {
  const stencilMat = new MeshBasicMaterial();
  stencilMat.depthWrite = false;
  stencilMat.colorWrite = false;
  stencilMat.stencilWrite = true;
  stencilMat.stencilRef = STENCIL_REF;
  stencilMat.stencilFunc = AlwaysStencilFunc;
  stencilMat.stencilZPass = ReplaceStencilOp;
  const stencilMesh = new Mesh(geometry, stencilMat);
  stencilMesh.position.copy(position2);
  stencilMesh.scale.set(size2, size2, size2);
  scene.add(stencilMesh);
  return stencilMesh;
}
function prepareMaterialForStencilMask(material) {
  material.stencilWrite = false;
  material.stencilRef = STENCIL_REF;
  material.stencilFunc = EqualStencilFunc;
}
function toggleStencilMask(allowed, material) {
  material.stencilWrite = allowed;
}

