function createPredefinedRegionsDetector(texture) {
  let canvas = document.createElement("canvas");
  canvas.width = texture.image.width;
  canvas.height = texture.image.height;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Could not get the context");
  const width = canvas.width;
  const height = canvas.height;
  context.filter = `url(data:image/svg+xml;base64,${FILTER_ANTIALIAS_AS_BASE64STRING}#filter)`;
  context.imageSmoothingEnabled = false;
  context.drawImage(texture.image, 0, 0);
  Debugger.debug(Flag.EXPORT, () => exportCanvas(canvas, "predefined_region_canvas", ImageFormat.PNG));
  const pixelsData = context.getImageData(0, 0, width, height).data;
  const stride = pixelsData.length / width / height;
  const pixels = pixelsData.filter((pixel, index2) => {
    return index2 % RGBA_BLUE_OFFSET === 0 && index2 % stride !== 0;
  });
  const pixelAccessor = createPixelArrayAccessor(pixels, width, 1);
  texture.dispose();
  context.clearRect(0, 0, width, height);
  canvas = void 0;
  return {
    /**
     * Returns predefined region under {@link uv} texture coordinate.
     * Regions are coded within the blue channel.
     * @param {Vector2} uv Texture coordinate.
     * @returns {?PredefinedInpaintingValue}
    */
    getRegionType(uv3) {
      const x = floor2(uv3.x * width);
      const y = floor2((1 - uv3.y) * height);
      const index2 = pixelAccessor.getPixelIndex(x, y);
      const blue = pixelAccessor.getPixelComponent(index2, 0);
      if (blue === 0) return null;
      for (let i = 0; i < PREDEFINED_REGIONS_DEFINITION.length; i++) {
        const region = PREDEFINED_REGIONS_DEFINITION[i];
        if (abs2(region.color - blue) <= REGION_THRESHOLD) {
          Debugger.debug(Flag.SHADER, () => console.log(`${region.type.description}: ${blue}, diff: ${region.color - blue}`));
          return region.type;
        }
      }
      return null;
    }
  };
}
function createPredefinedRegionsDefinitions() {
  const regions = [];
  let color = 1;
  let index2 = 0;
  Object.values(PredefinedInpainting).forEach((type2) => {
    const regionInfo = PREDEFINED_REGION_PERIMETER_BARYCOORDS.find((item) => item.type === type2);
    regions.push(new PredefinedRegionDefinition({
      type: type2,
      color: round2(color * 255),
      index: index2,
      perimeter: regionInfo.perimeter,
      symmetric: regionInfo.symmetric,
      ignoreInpainting: regionInfo.ignoreInpainting
    }));
    index2++;
    color = 1 - PREDEFINED_REGION_COLOR_STEP * index2;
  });
  Debugger.debug(Flag.EXPORT, () => printPredefinedRegions(regions));
  return regions;
}
function createPredefinedRegions(model, parent) {
  const predefinedRegions = [];
  PREDEFINED_REGIONS_DEFINITION.forEach((regionDefinition) => {
    const region = new PredefinedRegion({ regionDefinition, model, parent });
    predefinedRegions.push(region);
  });
  return predefinedRegions;
}
