function curveMaterial(simulationType) {
  switch (simulationType) {
    case SimulationType.FACE:
      return CURVE_MATERIAL_FACE;
    case SimulationType.BREAST:
      return CURVE_MATERIAL_BREAST;
    case SimulationType.FULL_BODY:
      return CURVE_MATERIAL_BODY;
    case SimulationType.BODY:
      return CURVE_MATERIAL_BODY;
    default:
      throw new Error(`${curveMaterial.name}: ${NEEDS_TO_BE_IMPLEMENTED_FOR_ERROR_MESSAGE} ${simulationType}`);
  }
}
function getCustomImageDataMask(customRegion, width, height) {
  function tx(x) {
    return Math.floor(x * width);
  }
  function ty(y) {
    return Math.floor((1 - y) * height);
  }
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  context.fillStyle = "white";
  context.strokeStyle = "white";
  context.filter = `url(data:image/svg+xml;base64,${FILTER_ANTIALIAS_AS_BASE64STRING}#filter)`;
  context.imageSmoothingEnabled = false;
  context.lineWidth = 6 * width / BASE_TEXTURE_SIZE;
  context.lineJoin = "round";
  const path = new Path2D();
  const uvs = customRegion.uvs;
  path.moveTo(tx(uvs[0].x), ty(uvs[0].y));
  for (let i = 1; i < uvs.length; i++) {
    path.lineTo(tx(uvs[i].x), ty(uvs[i].y));
  }
  path.closePath();
  context.fill(path);
  context.stroke(path);
  const imageData = context.getImageData(0, 0, width, height);
  context.clearRect(0, 0, width, height);
  return imageData;
}

