    PLANE_MATERIAL.color.setHex(style.planeColor);
    LINE_MATERIAL.color.setHex(style.lineColor);
    ARROW_MATERIAL.color.setHex(style.arrowColor);
    DOTTED_LINES_PRIMARY_MATERIAL.color.setHex(style.dottedLinePrimaryColor);
