  /**
   * Checks whether two or more parameter simulations are equal in terms of shape.
   * @param {string[]} simulationIds Simulations to compare.
   * @returns {boolean} True if equal, false otherwise.
   */
  areSimulationsEqual(simulationIds) {
    checkTypes(arguments, ["Array"]);
    if (simulationIds.length < 2)
      return true;
    const model = this.getSimulationModel(simulationIds[0]);
    for (let i = 1, length = simulationIds.length; i < length; i++) {
      if (!this.getSimulationModel(simulationIds[i]).equals(model))
        return false;
    }
    return true;
  }
  /**
   * Sets the brightness for a parameter simulation.
   * If not specified, sets for all simulations.
   * @param {number} brightness Target brightness in the [0, 1] range. 0.5 is the default brightness.
   * @param {string} [simulationId] Target simulation, if any.
   */
  setBrightness(brightness, simulationId = "") {
    const clothingTool = this._getTool(CLOTHING_TOOL_ID);
    if (!clothingTool) return;
    if (simulationId !== "") {
      const model = this.getSimulationModel(simulationId);
      clothingTool.setBrightness(brightness, model);
      this._dispatchSimulationEvent(SimulationEvent.Type.CHANGE, false, simulationId);
    } else {
      clothingTool.setBrightness(brightness, this._patient.beforeModel);
      for (const model of this._getSimulationModels()) {
        clothingTool.setBrightness(brightness, model);
      }
      this._dispatchSimulationEvent(SimulationEvent.Type.CHANGE, false);
    }
  }
