// src/constants/outside_vertices.js
function outsideVertices(simulationType) {
  switch (simulationType) {
    case SimulationType.FACE:
      return [3936];
    // Back of the left ear
    case SimulationType.BREAST:
      return [292];
    // Center of the back
    case SimulationType.BODY:
      return [213];
    // Between the legs
    case SimulationType.FULL_BODY:
      return [11025, 12802, 2452, 13407, 3556];
    // Vertices that are on the head and the limbs, never on the torso
    default:
      throw new Error(`${outsideVertices.name}: ${NEEDS_TO_BE_IMPLEMENTED_FOR_ERROR_MESSAGE} ${simulationType.description}`);
  }
}

// src/utils/symbol.js
function findSymbolFromDescription(symbols, description) {
  return Object.values(symbols).find((symbol) => symbol.description === description) ?? null;
}
function findAssessmentSymbol(description) {
  return findSymbolFromDescription(MeasurementType, description) ?? findSymbolFromDescription(CustomAssessmentType, description);
}

