      bottomOuterFaces: isLeft ? LEFT_BREAST_BOTTOM_OUTER_QUADRANT_FACES[simulationType] : RIGHT_BREAST_BOTTOM_OUTER_QUADRANT_FACES[simulationType],
      bottomInnerFaces: isLeft ? LEFT_BREAST_BOTTOM_INNER_QUADRANT_FACES[simulationType] : RIGHT_BREAST_BOTTOM_INNER_QUADRANT_FACES[simulationType],
      topVertex: isLeft ? LEFT_BREAST_TOP[simulationType] : RIGHT_BREAST_TOP[simulationType],
      bottomVertex: isLeft ? LEFT_BREAST_BOTTOM[simulationType] : RIGHT_BREAST_BOTTOM[simulationType],
