      topInnerVertex: isLeft ? LEFT_BREAST_TOP_INNER[simulationType] : RIGHT_BREAST_TOP_INNER[simulationType],
      bottomOuterVertex: isLeft ? LEFT_BREAST_BOTTOM_OUTER[simulationType] : RIGHT_BREAST_BOTTOM_OUTER[simulationType],
