    this.#topRightCurve = new QuadraticBezierCurve3(this.#rightBodyMarkPosition, new Vector3(this.#rightBodyMarkPosition.x, this.#topBodyMarkPosition.y, this.#topBodyMarkPosition.z), this.#topBodyMarkPosition);
    this.#bottomLeftCurve = new QuadraticBezierCurve3(this.#leftBodyMarkPosition, new Vector3(this.#leftBodyMarkPosition.x, this.#bottomBodyMarkPosition.y, this.#bottomBodyMarkPosition.z), this.#bottomBodyMarkPosition);
    this.#bottomRightCurve = new QuadraticBezierCurve3(this.#rightBodyMarkPosition, new Vector3(this.#rightBodyMarkPosition.x, this.#bottomBodyMarkPosition.y, this.#bottomBodyMarkPosition.z), this.#bottomBodyMarkPosition);
    this.#topLeftDottedLine = this.#createDottedLine("top_left", this.#topLeftCurve.getSpacedPoints(Math.round(this.#topLeftCurve.getLength() * this._customPointMultiplier)));
    this.#topRightDottedLine = this.#createDottedLine("top_right", this.#topRightCurve.getSpacedPoints(Math.round(this.#topRightCurve.getLength() * this._customPointMultiplier)));
    this.#bottomLeftDottedLine = this.#createDottedLine("bottom_left", this.#bottomLeftCurve.getSpacedPoints(Math.round(this.#bottomLeftCurve.getLength() * this._customPointMultiplier)));
    this.#bottomRightDottedLine = this.#createDottedLine("bottom_right", this.#bottomRightCurve.getSpacedPoints(Math.round(this.#bottomRightCurve.getLength() * this._customPointMultiplier)));
    this.#verticalPlane = this.#createPlane("vertical");
    this.#verticalPlane.rotateY(degToRad2(90));
    this.#horizontalPlane = this.#createPlane("horizontal");
