  #leftHipPosition = new Vector3();
  #rightHipPosition = new Vector3();
  #leftClaviclePosition = new Vector3();
  #rightClaviclePosition = new Vector3();
  #vertexWaistPosition = new Vector3();
  #leftWaistPosition = new Vector3();
  #rightWaistPosition = new Vector3();
