  #startFrontLeftDragPathLimit = new Vector3();
  #endFrontLeftDragPathLimit = new Vector3();
  #frontRightDragPath = new Line3();
  #startFrontRightDragPathLimit = new Vector3();
  #endFrontRightDragPathLimit = new Vector3();
  #leftWaistDragPath = new Line3();
  #startLeftWaistDragPathLimit = new Vector3();
  #endLeftWaistDragPathLimit = new Vector3();
  #rightWaistDragPath = new Line3();
  #startRightWaistDragPathLimit = new Vector3();
  #endRightWaistDragPathLimit = new Vector3();
  #backLeftDragPath = new Line3();
  #startBackLeftDragPathLimit = new Vector3();
  #endBackLeftDragPathLimit = new Vector3();
  #backRightDragPath = new Line3();
  #startBackRightDragPathLimit = new Vector3();
  #endBackRightDragPathLimit = new Vector3();
  #frontLeftHipBodyMarkPosition = new Vector3();
  #frontRightHipBodyMarkPosition = new Vector3();
  #backLeftHipBodyMarkPosition = new Vector3();
  #backRightHipBodyMarkPosition = new Vector3();
  #leftWaistBodyMarkPosition = new Vector3();
  #rightWaistBodyMarkPosition = new Vector3();
