    this.#frontRightDragPath = this.#computeDragPath(this.#startFrontRightDragPathLimit, this.#endFrontRightDragPathLimit, this.#frontRightHipBodyMarkPosition, this.#startYHipPath, this.#endYHipPath, this.#frontDragPlane);
    this.#backLeftDragPath = this.#computeDragPath(this.#startBackLeftDragPathLimit, this.#endBackLeftDragPathLimit, this.#backLeftHipBodyMarkPosition, this.#startYHipPath, this.#endYHipPath, this.#backDragPlane);
    this.#backRightDragPath = this.#computeDragPath(this.#startBackRightDragPathLimit, this.#endBackRightDragPathLimit, this.#backRightHipBodyMarkPosition, this.#startYHipPath, this.#endYHipPath, this.#backDragPlane);
    this.#leftWaistDragPath = this.#computeDragPath(this.#startLeftWaistDragPathLimit, this.#endLeftWaistDragPathLimit, this.#leftWaistBodyMarkPosition, this.#startYHipPath, this.#endYHipPath, this.#frontDragPlane);
    this.#rightWaistDragPath = this.#computeDragPath(this.#startRightWaistDragPathLimit, this.#endRightWaistDragPathLimit, this.#rightWaistBodyMarkPosition, this.#startYHipPath, this.#endYHipPath, this.#frontDragPlane);
