    this.#computeBodyMarkPosition(this.#frontRightHipBodyMark, this.#frontRightHipBodyMarkPosition, this.#rightHipPosition, this.#frontDragPlane);
    this.#computeBodyMarkPosition(this.#backLeftHipBodyMark, this.#backLeftHipBodyMarkPosition, this.#leftHipPosition, this.#backDragPlane);
    this.#computeBodyMarkPosition(this.#backRightHipBodyMark, this.#backRightHipBodyMarkPosition, this.#rightHipPosition, this.#backDragPlane);
