      for (let i = length - 1; --i >= 0; ) {
        renderingContext2D.lineTo(this.#selectedPointsB[i].x, this.#selectedPointsB[i].y);
      }
      renderingContext2D.bezierCurveTo(this.#controlPointStartB.x, this.#controlPointStartB.y, this.#controlPointStartA.x, this.#controlPointStartA.y, this.#selectedPointsA[0].x, this.#selectedPointsA[0].y);
