// src/materials/TransitionMaterial.js
var TransitionMaterial = class {
  #material;
  /**
   * Creates a {@link TransitionMaterial}.
   * @param {SimulationTypeValue} simulationType The simulation type.
   */
  constructor(simulationType) {
    const uniforms = UniformsUtils.merge([
      // pass threejs light uniforms to the skin material
      UniformsLib.lights,
      {
        map1: new Uniform(null),
        map2: new Uniform(null),
        interpolationValue: new Uniform(0),
        opacity: new Uniform(1),
        brightness: new Uniform(DEFAULT_BRIGHTNESS),
        shininess: new Uniform(DEFAULT_SHININESS),
        alphaMap: new Uniform(null),
        useAlphaMap: new Uniform(false),
        // full-body textures
        fullBodyHeadMap: new Uniform(null),
        fullBodyHeadAlphaMap: new Uniform(null),
        fullBodyLimbsMap: new Uniform(null),
        fullBodyLimbsAlphaMap: new Uniform(null),
        useFullBodyHeadAlphaMap: new Uniform(false),
        useFullBodyLimbsAlphaMap: new Uniform(false)
      }
    ]);
    this.#material = new ShaderMaterial({
      uniforms,
      vertexShader: skin_default2,
      fragmentShader: transition_default,
      transparent: true,
      blendSrc: SrcAlphaFactor,
      blendDst: OneMinusSrcAlphaFactor,
      lights: true
    });
    this.#material.defines[SHADER_MODEL_TYPE[SimulationType.BREAST]] = simulationType === SimulationType.BREAST;
    this.#material.defines[SHADER_MODEL_TYPE[SimulationType.FACE]] = simulationType === SimulationType.FACE;
    this.#material.defines[SHADER_MODEL_TYPE[SimulationType.FULL_BODY]] = simulationType === SimulationType.FULL_BODY;
  }
  /**
   * Returns the underlying threejs material instance.
   * @returns {Material}
   */
  get material() {
    return this.#material;
  }
  /**
   * Sets the configuration parameters.
   * @param {number} opacity Opacity of the material.
   * @param {number} brightness Model brightness when using lights.
   * @param {number} shininess Model shininess when using lights.
   * @param {Texture} alphaMap Alpha map used for occulting parts of the model.
   * @param {boolean} useAlphaMap Whether the alpha map is used.
   */
  setParameters(opacity, brightness, shininess, alphaMap, useAlphaMap) {
    this.#material.uniforms.opacity.value = opacity;
    this.#material.uniforms.brightness.value = normalizedToRange(MIN_BRIGHTNESS, MAX_BRIGHTNESS, brightness);
    this.#material.uniforms.shininess.value = shininess;
    this.#material.uniforms.alphaMap.value = alphaMap;
    this.#material.uniforms.useAlphaMap.value = useAlphaMap;
  }
  /**
   * Sets the full-body textures.
   * @param {{head: Texture, headAlpha: Texture, limbs: Texture, limbsAlpha: Texture}} textures Full body textures.
   * @param {boolean} useFullBodyHeadAlphaMap Whether to use the full-body head alpha map.
   * @param {boolean} useFullBodyLimbsAlphaMap Whether to use the full-body limbs alpha map.
   */
  setFullBodyTextures(textures, useFullBodyHeadAlphaMap, useFullBodyLimbsAlphaMap) {
    this.#material.uniforms.fullBodyHeadMap.value = textures.head;
    this.#material.uniforms.fullBodyHeadAlphaMap.value = textures.headAlpha;
    this.#material.uniforms.fullBodyLimbsMap.value = textures.limbs;
    this.#material.uniforms.fullBodyLimbsAlphaMap.value = textures.limbsAlpha;
    this.#material.uniforms.useFullBodyHeadAlphaMap.value = useFullBodyHeadAlphaMap;
    this.#material.uniforms.useFullBodyLimbsAlphaMap.value = useFullBodyLimbsAlphaMap;
  }
  /**
   * Sets the transition parameters.
   * @param {Texture} map1 First transition map.
   * @param {Texture} map2 Second transition map.
   * @param {number} interpolationValue Interpolation value in the [0, 1] range.
   */
  setMaps(map1, map2, interpolationValue) {
    this.#material.uniforms.map1.value = map1;
    this.#material.uniforms.map2.value = map2;
    this.#material.uniforms.interpolationValue.value = interpolationValue;
  }
  /**
   * Disposes the material and all of its contents.
   * The alpha map is not disposed.
   */
  dispose() {
    this.material.dispose();
    this.material.map1 = void 0;
    this.material.map2 = void 0;
    this.material.alphaMap = void 0;
    this.material.fullBodyHeadMap = void 0;
    this.material.fullBodyHeadAlphaMap = void 0;
    this.material.fullBodyLimbsMap = void 0;
    this.material.fullBodyLimbsAlphaMap = void 0;
    this.#material = void 0;
  }
};

// src/simulation/tools/MorphTransitionTool.js
var MorphTransitionTool = class extends Tool {
  /** @type {RenderTextureScene} */
  #renderer;
  /** @type {TransitionMaterial} */
  #transitionMaterial;
  /** @type {Model[]} */
  #transitionModels = [];
  /** @type {Texture[]} */
  #transitionTextures = [];
  /** @type {number[]} */
  #fullScanDeformationIndices;
  /** @type {SimulationTypeValue} */
  #simulationType;
  #renderScene = new Scene();
  // per model information (container-like behavior)
  /** @type {Map<Model, WebGLRenderTarget>} */
  #renderTargets = /* @__PURE__ */ new Map();
  // Memory optimization
  #vector = new Vector3();
  /**
   * Creates a {@link MorphTransitionTool}.
   * @param {object} parameters Constructor parameters.
   * @param {RenderTextureScene} parameters.renderer Renderer to use.
   * @param {SimulationTypeValue} parameters.simulationType The type of the simulation.
   * @param {number[]} [parameters.fullScanDeformationIndices] Full-scan indices that can be deformed, if any.
   */
  constructor(parameters) {
    checkTypes([parameters, parameters.renderer], ["object", RenderTextureScene]);
    if (parameters.fullScanDeformationIndices) checkTypes([parameters.fullScanDeformationIndices], ["Array"]);
    super({ id: MORPH_TRANSITION_TOOL_ID, editType: ToolEditType.ALL });
    this.#simulationType = parameters.simulationType;
    this.#transitionMaterial = new TransitionMaterial(this.#simulationType);
    this.#renderer = parameters.renderer;
    this.#fullScanDeformationIndices = parameters.fullScanDeformationIndices;
    this.toggle(false);
  }
  /**
   * @inheritdoc
   * @type {Tool['onCreateModel']}
   */
  onCreateModel(model) {
  }
  /**
   * @inheritdoc
   * @type {Tool['reset']}
   */
  reset(model) {
  }
  /**
   * @override
   * Interpolates between the current simulation and the original model given a parameter factor.
   * Both models must be topologically equal.
   * @param {Model} model Target simulation model.
   * @param {object} parameters Target parameters.
   * @param {number} parameters.alpha Interpolation factor in the [0, 1] range. 0 = original model, 1 = target simulation.
   */
  action(model, parameters) {
    checkTypes([model, parameters.alpha], [Model, "number"]);
    const maxModels = this.#transitionModels.length;
    if (maxModels <= 1) return;
    let alpha = MathUtils.clamp(parameters.alpha, 0, 1);
    alpha *= maxModels - 1;
    let modelIndex = Math.floor(alpha);
    modelIndex = MathUtils.clamp(modelIndex, 0, maxModels - 2);
    alpha -= modelIndex;
    const originalModel = this.#transitionModels[modelIndex];
    const originalTexture = this.#transitionTextures[modelIndex];
    const targetModel = this.#transitionModels[modelIndex + 1];
    const targetTexture = this.#transitionTextures[modelIndex + 1];
    this.#applyTransition(model.vertices, originalModel.vertices, targetModel.vertices, alpha);
    if (this.#fullScanDeformationIndices) {
      this.#applyTransition(model.fullScanModel.vertices, originalModel.fullScanModel.vertices, targetModel.fullScanModel.vertices, alpha, this.#fullScanDeformationIndices);
    }
    this.morphTexture(model, originalTexture, targetTexture, alpha);
    model.replaceMaterial(this.#transitionMaterial.material, true);
  }
  /**
   * Applies the transition between the original and target models to the current model.
   * It interpolates each vertex position and normal.
   * @param {Vertex[]} currentVertices Current model vertices.
   * @param {Vertex[]} originalVertices Original model vertices.
   * @param {Vertex[]} targetVertices Target model vertices.
   * @param {number} alpha Interpolation factor in the [0, 1] range. 0 = original model, 1 = target simulation.
   * @param {number[]} [indices] Subset of vertices to be transitioned. If undefined, all vertices are transitioned.
   */
  #applyTransition(currentVertices, originalVertices, targetVertices, alpha, indices = void 0) {
    const vertexCount = indices ? indices.length : currentVertices.length;
    for (let i = 0; i < vertexCount; i++) {
      const index2 = indices ? indices[i] : i;
      const current = currentVertices[index2];
      const original = originalVertices[index2];
      const target = targetVertices[index2];
      this.#vector.copy(original.position).lerp(target.position, alpha);
      current.position.copy(this.#vector);
      this.#vector.copy(original.normal).lerp(target.normal, alpha);
      current.normal.copy(this.#vector);
    }
  }
  /**
   * Interpolates the parameter textures and applies them to {@link model}.
   * @param {Model} model Model where the transition takes place.
   * @param {Texture} texture1 First transition texture ({@link alpha} = 0).
   * @param {Texture} texture2 Second transition texture ({@link alpha} = 1).
   * @param {number} alpha Interpolation value in the range [0, 1].
   */
  morphTexture(model, texture1, texture2, alpha) {
    this.#transitionMaterial.setMaps(texture1, texture2, alpha);
  }
  /**
   * Toggles the transition mode by swapping the model material and precomputing the necessary textures.
   * @param {boolean} enable Whether transition is enabled.
   * @param {Model} model Target model where the transition will take place.
   * @param {Model[]} [models] Models to be transitioned over.
   */
  toggleTransition(enable, model, models = void 0) {
    if (enable && models !== void 0) {
      this.#transitionModels = models;
      for (const texture of this.#transitionTextures) texture.dispose();
      this.#transitionTextures.length = 0;
      for (const model2 of models) {
        const renderTarget = this.#getRenderTarget(model2);
        const texture = this.#getRenderTargetTexture(model2, renderTarget);
        this.#transitionTextures.push(texture);
      }
      this.#transitionMaterial.setParameters(model.opacity, model.brightness, model.shininess, model.alphaMap, model.useAlphaMap);
      if (this.#simulationType === SimulationType.FULL_BODY) {
        this.#transitionMaterial.setFullBodyTextures(model.getFullBodyTextures(), model.useFullBodyHeadAlphaMap, model.useFullBodyLimbsAlphaMap);
      }
    } else if (!enable) {
      model.restoreMaterial(true);
    }
    this.toggle(enable);
  }
  /**
   * Returns the render target for a parameter model.
   * @param {Model} model Target model.
   * @returns {WebGLRenderTarget}
   */
  #getRenderTarget(model) {
    const hasModel = this.#renderTargets.has(model);
    const renderTarget = hasModel ? this.#renderTargets.get(model) : new WebGLRenderTarget();
    if (!hasModel)
      this.#renderTargets.set(model, renderTarget);
    return renderTarget;
  }
  /**
   * Returns the model's texture as a render target texture.
   * @param {Model} model The target model.
   * @param {WebGLRenderTarget} renderTarget The render target.
   * @returns {Texture} The model's texture.
   */
  #getRenderTargetTexture(model, renderTarget) {
    const unwrapMaterial = model.createMaterial(BakeType.VR);
    const mesh = new Mesh(model.mesh.geometry, unwrapMaterial.material);
    this.#renderScene.clear();
    this.#renderScene.add(mesh);
    this.#renderScene.background = model.skinTextureMap;
    renderTarget.setSize(model.textureSize.x, model.textureSize.y);
    this.#renderer.render(renderTarget, this.#renderScene);
    model.restoreMaterial();
    unwrapMaterial.dispose();
    return renderTarget.texture;
  }
  /**
   * @inheritdoc
   * @type {Tool['disposeElements']}
   */
  disposeElements(model) {
    if (this.#renderTargets.has(model)) {
      const renderTarget = this.#renderTargets.get(model);
      this.#renderTargets.delete(model);
      renderTarget.dispose();
    }
  }
};

