var LaplacianDeformation = class _LaplacianDeformation {
  /**
   * Laplacian deformation constructor.
   * @param {Vertex[]} vertices Original vertices to build from.
   */
  constructor(vertices) {
    if (this.constructor === _LaplacianDeformation) {
      throw new Error(`${_LaplacianDeformation.name}: ${ABSTRACT_CLASS_CANNOT_BE_INSTANTIATED_ERROR_MESSAGE}`);
    }
    this._vertices = vertices;
    this._precomputed = false;
    this._updated = false;
    this._n = vertices.length;
    this._p = [new Array(this._n), new Array(this._n), new Array(this._n)];
  }
  /**
   * Precomputes the laplacian deformation given a matrix and a set of free and handle vertices.
   * Sets of vertices must not overlap.
   * @abstract
   * @param {Matrix} L Laplacian matrix.
   * @param {number[]} free Free vertices.
   * @param {number[]} handle Handle vertices.
   */
  precompute(L, free, handle) {
    this._free = free;
    this._handle = handle;
    this._precomputed = true;
  }
  /**
   * Updates the laplacian deformation with the current state of the geometry.
   * The parameter vertices are expected to be the same ones passed in the constructor in terms of size and order.
   * Does nothing and returns false if {@link precompute} hasn't been called.
   * @param {Vertex[]} vertices Vertices to update with.
   * @returns {boolean} Whether the update was successful.
   */
  update(vertices) {
    if (!this._precomputed)
      return false;
    for (let i = 0; i < this._n; i++) {
      const v5 = vertices[i].position;
      this._p[0][i] = v5.x;
      this._p[1][i] = v5.y;
      this._p[2][i] = v5.z;
    }
    this._updated = true;
    return true;
  }
  /**
   * Deforms the geometry given its current state and its last update.
   * Does nothing and returns false if {@link update} hasn't been called.
   * @param {Vertex[]} vertices Vertices to update.
   * @returns {boolean} Whether the update was successful.
   */
  deform(vertices) {
    return this._updated;
  }
};

