  const baseTop = LEFT_BREAST_TOP_OUTER_LINE[simulationType].concat(LEFT_BREAST_TOP_INNER_LINE[simulationType]).concat(RIGHT_BREAST_TOP_OUTER_LINE[simulationType]).concat(RIGHT_BREAST_TOP_INNER_LINE[simulationType]);
  const baseBottom = LEFT_BREAST_BOTTOM_OUTER_LINE[simulationType].concat(LEFT_BREAST_BOTTOM_INNER_LINE[simulationType]).concat(RIGHT_BREAST_BOTTOM_OUTER_LINE[simulationType]).concat(RIGHT_BREAST_BOTTOM_INNER_LINE[simulationType]);
