  free = free.filter((f) => !handle.includes(f));
  const leftUpperLine = LEFT_BREAST_VERTICAL_UPPER_LINE[simulationType];
  const rightUpperLine = RIGHT_BREAST_VERTICAL_UPPER_LINE[simulationType];
  const extra = LEFT_TORSO_WITHOUT_BREAST[simulationType].concat(RIGHT_TORSO_WITHOUT_BREAST[simulationType]);
  handle = setLaplacianWeights(softConstraintsDeformation, model, handle, SOFT_CONSTRAINTS_BREAST_HANDLE_LAMBDA);
  setLaplacianWeights(softConstraintsDeformation, model, lateral, SOFT_CONSTRAINTS_BREAST_LATERAL_HANDLE_LAMBDA);
  setLaplacianWeights(softConstraintsDeformation, model, baseBottom, SOFT_CONSTRAINTS_BREAST_BOTTOM_BASE_HANDLE_LAMBDA);
  setLaplacianWeights(softConstraintsDeformation, model, baseTop, SOFT_CONSTRAINTS_BREAST_TOP_BASE_HANDLE_LAMBDA);
  setLaplacianWeights(softConstraintsDeformation, model, leftUpperLine, SOFT_CONSTRAINTS_BREAST_TOP_BASE_HANDLE_LAMBDA);
  setLaplacianWeights(softConstraintsDeformation, model, rightUpperLine, SOFT_CONSTRAINTS_BREAST_TOP_BASE_HANDLE_LAMBDA);
  free = setLaplacianWeights(softConstraintsDeformation, model, free, SOFT_CONSTRAINTS_BREAST_FREE_LAMBDA);
  setLaplacianWeights(softConstraintsDeformation, model, lateralArea, SOFT_CONSTRAINTS_BREAST_LATERAL_FREE_LAMBDA);
