function loadObject(file) {
  checkTypes([file], ["string"]);
  return new Promise((resolve, reject) => {
    const loader = new FileLoader();
    loader.setResponseType("text").load(
      file,
      (data) => {
        if (typeof data === "string")
          resolve(JSON.parse(data));
        else
          reject(new Error(FILE_CANNOT_BE_PARSED_ERROR_MESSAGE));
      },
      void 0,
      (error) => {
        reject(error);
      }
    );
  });
}

