// src/simulation/tools/custom_region_treatment/CustomRegion.js
var CustomRegion = class {
  // attributes
  /** @type {Model} */
  #model = null;
  /** @type {Mesh} */
  #drawingLine = null;
  // the graphical curve
  #offset = 0;
  // offset to avoid Z-fighting when painting curve
  // memory optimization
  #positions = [];
  // array with curve's positions
  #hits = [];
  // all the hits, needed for computing the faces within the region
  #normal = new Vector3();
  #position = new Vector3();
  #startPosition = new Vector3();
  #endPosition = new Vector3();
  #rayOrigin = new Vector3();
  #rayDirection = new Vector3();
  /**
   * Creates a {@link CustomRegion}.
   * @param {Model} model Model to which the custom region will be added.
   */
  constructor(model) {
    checkTypes([model], [Model]);
    this.#offset = curveOffset(model.type);
    this.#drawingLine = this.#createLineObject(model.type);
    this.#drawingLine.name = `${model.name}-custom-region`;
    model.add(this.#drawingLine);
    this.#model = model;
  }
  /**
   * Creates and configures the drawing line object.
   * @param {SimulationTypeValue} simulationType
   * @returns {object} The resulting line mesh object.
   */
  #createLineObject(simulationType) {
    const lineMaterial = curveMaterial(simulationType);
    const lineObject = new Mesh(new MeshLineGeometry(), lineMaterial);
    lineObject.renderOrder = OVERLAY_RENDER_ORDER;
    return lineObject;
  }
  /**
   * Gets the uvs defining the custom region.
   * @returns {Vector2[]}
   */
  get uvs() {
    return this.#hits.map((hit) => hit.uv);
  }
  /**
   * Gets the hits defining the custom region.
   * @returns {Hit[]}
   */
  get hits() {
    return this.#hits;
  }
  /**
   * Gets the region's name.
   * @returns {string}
   */
  get name() {
    return this.#drawingLine.name;
  }
  /**
   * Adds a hit to the custom region.
   * @param {Hit} hit The hit on the model.
   */
  addHit(hit) {
    this.#hits.push(this.#cloneHit(hit));
    this.#normal.copy(hit.normal);
    this.#position.copy(hit.point);
    this.#model.worldToLocal(this.#position);
    this.#positions.push(this.#position.clone().add(this.#normal.multiplyScalar(this.#offset)));
    if (this.#positions.length > 1)
      this.#drawingLine.geometry.setPoints(this.#positions);
  }
  /**
   * Returns whether the region is valid.
   * @returns {boolean}
   */
  #isValid() {
    return this.#hits.length > MINIMUM_POINTS_FOR_CUSTOM_REGION;
  }
  /**
   * Consolidates a preview custom region. Returns whether the region has been consolidated.
   * @returns {boolean}
   */
  consolidate() {
    if (!this.#isValid()) {
      this.dispose();
      return false;
    }
    this.#startPosition = this.#positions[this.#positions.length - 1];
    this.#endPosition = this.#positions[0];
    const distance = this.#startPosition.distanceTo(this.#endPosition);
    const pointsToAdd = Math.floor(distance / 0.5);
    for (let i = 1; i < pointsToAdd; i++) {
      const t2 = i / pointsToAdd;
      this.#position.lerpVectors(this.#startPosition, this.#endPosition, t2);
      this.#normal.copy(this.#hits[this.#hits.length - 1].normal);
      this.#rayOrigin.copy(this.#position).add(this.#normal.multiplyScalar(2.5));
      this.#rayDirection.subVectors(this.#position, this.#rayOrigin).normalize();
      const raycast3 = this.#model.raycast(this.#rayOrigin, this.#rayDirection, Raycast.Type.DEFAULT, true, false);
      if (!raycast3.miss) {
        const hit = raycast3.hit;
        this.#hits.push(this.#cloneHit(hit));
        this.#positions.push(this.#position.clone().add(hit.face.normal.clone().multiplyScalar(this.#offset)));
      }
      Debugger.debug(Flag.MODEL, () => {
        const arrow = new ArrowHelper(this.#rayDirection, this.#rayOrigin, 2, raycast3.miss ? 16711680 : 65280, 0.2, 0.1);
        this.#model.add(arrow);
        setTimeout(() => {
          arrow.removeFromParent();
        }, 5e3);
      });
    }
    this.#positions.push(this.#positions[0]);
    this.#hits.push(this.#cloneHit(this.#hits[0]));
    this.#drawingLine.geometry.setPoints(this.#positions);
    return true;
  }
  /**
   * Removes close hits that are within a minimum distance.
   * @param {number} minDistanceSquared The minimum distance squared.
   * @returns {Hit[]} The hits after removing close hits.
   */
  removeCloseHits(minDistanceSquared = 0.5 * 0.5) {
    if (this.#hits.length === 0) return [];
    const filteredHits = [this.#hits[0]];
    const filteredPositions = [this.#positions[0]];
    for (let i = 1; i < this.#hits.length; i++) {
      const lastFilteredPosition = filteredPositions[filteredPositions.length - 1];
      if (this.#positions[i].distanceToSquared(lastFilteredPosition) < minDistanceSquared) continue;
      filteredHits.push(this.#hits[i]);
      filteredPositions.push(this.#positions[i]);
    }
    if (!filteredHits[0].point.equals(filteredHits[filteredHits.length - 1].point)) {
      filteredHits.push(this.#hits[this.#hits.length - 1]);
      filteredPositions.push(this.#positions[this.#positions.length - 1]);
    }
    this.#hits = filteredHits;
    this.#positions = filteredPositions;
    this.#drawingLine.geometry.setPoints(this.#positions);
    return this.#hits;
  }
  /**
   * Clones a hit object.
   * @param {Hit} hit The hit object to clone.
   * @returns {Hit} The cloned hit object.
   */
  #cloneHit(hit) {
    return {
      point: hit.point.clone(),
      normal: hit.normal.clone(),
      uv: hit.uv.clone(),
      faceIndex: hit.faceIndex,
      face: {
        a: hit.face.a,
        b: hit.face.b,
        c: hit.face.c
      }
    };
  }
  /**
   * Disposes the region.
   */
  dispose() {
    this.#positions.length = 0;
    this.#hits.length = 0;
    if (!this.#drawingLine) return;
    this.#drawingLine.geometry.drawRange.count = 0;
    this.#drawingLine.geometry.dispose();
    this.#drawingLine.removeFromParent();
  }
};

