    if (mask & 2) this.#debugAngles(afterModel, this.#outerFrontier, `${side}-a-outerFrontier`);
    if (mask & 4) this.#debugAngles(afterModel, this.#afterAreola, `${side}-a-afterAreola`);
    if (mask & 8) this.#debugAngles(afterModel, this.#oldAreolaFrontier, `${side}-a-oldAreolaFrontier`);
    if (mask & 16) this.#debugAngles(beforeModel, this.#beforeAreola, `${side}-a-beforeAreola`);
    if (mask & 32) this.#debugAngles(beforeModel, this.#newAreolaFrontier, `${side}-a-newAreolaFrontier`);
