// src/simulation/BreastSimulator.js
var BreastSimulator = class extends BaseBreastSimulator {
  /**
   * @inheritdoc
   * @type {Simulator['_assignTools']}
   * @returns {Tool[]}
   */
  _assignTools() {
    const tools = [];
    const beforeModel = this._patient.beforeModel;
    const renderer = this._renderer;
    const tweener = this._tweener;
    tools.push(new BreastBlendShapeTool(beforeModel));
    tools.push(new CurveTool({ beforeModel, skinPinch: this._patient.skinPinch, areolaRadii: this._patient.areolaRadii }));
    tools.push(new LipofillingTool(this._simulationType));
    tools.push(new FreeHandTool({ beforeModel }));
    tools.push(new FreeLineTool({ beforeModel }));
    tools.push(new ShapeSmoothingTool({ simulationType: this._simulationType }));
    tools.push(new RemapAreolaeTool({ renderer, beforeModel, areolaRadii: this._patient.areolaRadii }));
    tools.push(new MorphTransitionTool({ renderer, simulationType: this._simulationType, fullScanDeformationIndices: this._fullScanDeformationIndices }));
    tools.push(new ScarTool({ renderer, beforeModel }));
    tools.push(new DrawTool({ renderer, beforeModel }));
    tools.push(new StampTool({ renderer, simulationType: this._simulationType, textureSize: beforeModel.textureSize }));
    tools.push(new PredefinedAssessmentTool({ beforeModel, areolaRadii: this._patient.areolaRadii }));
    tools.push(new ClothingTool(this._patient.beforeModel));
    tools.push(new CoverTool({ tweener, beforeModel }));
    tools.push(new CustomAssessmentTool({ beforeModel }));
    tools.push(new BreastTopographyTool());
    tools.push(new CustomRegionTreatmentTool({ renderer, beforeModel }));
    return tools;
  }
};

