// src/utils/texture/face_mask_map.js
function getFaceMaskPositions(model) {
  function getEyePosition(leftEye, model2) {
    const ellipse = new Ellipse2D();
    if (leftEye) {
      ellipse.center = model2.getUV(MASK_LEFT_EYE_CENTER);
      ellipse.left = model2.getUV(MASK_LEFT_EYE_LEFT);
      ellipse.right = model2.getUV(MASK_LEFT_EYE_RIGHT);
      ellipse.top = model2.getUV(MASK_LEFT_EYE_TOP);
      ellipse.bottom = model2.getUV(MASK_LEFT_EYE_BOTTOM);
    } else {
      ellipse.center = model2.getUV(MASK_RIGHT_EYE_CENTER);
      ellipse.left = model2.getUV(MASK_RIGHT_EYE_LEFT);
      ellipse.right = model2.getUV(MASK_RIGHT_EYE_RIGHT);
      ellipse.top = model2.getUV(MASK_RIGHT_EYE_TOP);
      ellipse.bottom = model2.getUV(MASK_RIGHT_EYE_BOTTOM);
    }
    return ellipse;
  }
  function getMouthPosition(model2) {
    const ellipse = new Ellipse2D();
    ellipse.left = model2.getUV(MASK_MOUTH_LEFT);
    ellipse.right = model2.getUV(MASK_MOUTH_RIGHT);
    ellipse.top = model2.getUV(MASK_MOUTH_TOP);
    ellipse.bottom = model2.getUV(MASK_MOUTH_BOTTOM);
    ellipse.center.set((ellipse.left.x + ellipse.right.x) * 0.5, (ellipse.top.y + ellipse.bottom.y) * 0.5);
    return ellipse;
  }
  function getNosePosition(model2) {
    const ellipse = new Ellipse2D();
    ellipse.center = model2.getUV(MASK_NOSE_CENTER);
    ellipse.left = model2.getUV(MASK_NOSE_LEFT);
    ellipse.right = model2.getUV(MASK_NOSE_RIGHT);
    ellipse.top = model2.getUV(MASK_NOSE_TOP);
    ellipse.bottom = model2.getUV(MASK_NOSE_BOTTOM);
    return ellipse;
  }
  return {
    leftEye: getEyePosition(true, model),
    rightEye: getEyePosition(false, model),
    mouth: getMouthPosition(model),
    nose: getNosePosition(model)
  };
}

