// src/utils/texture/normal_map.js
var normalMapMaterial = new NormalMapMaterial({ avoidZFighting: true });
function createObjectSpaceNormalMap(renderer, model, width, height) {
  const renderTarget = new WebGLRenderTarget(width, height);
  model.replaceMaterial(normalMapMaterial.material);
  renderer.render(renderTarget, model.mesh);
  model.restoreMaterial();
  Debugger.debug(Flag.SHADER, () => exportRawPixels(renderer.getPixels(renderTarget), NORMAL_MAP_SIZE, NORMAL_MAP_SIZE, `${model.name}-normal-map`, ImageFormat.JPG));
  return renderTarget.texture;
}

