// src/deformations/laplacian/HardConstraintsDeformation.js
var HardConstraintsDeformation = class extends LaplacianDeformation {
  #x;
  // Linear system Ax = b solution
  #d;
  // Displacement vector to recycle memory
  constructor(vertices) {
    super(vertices);
    this.#d = new Vector3();
  }
  precompute(L, free, handle) {
    Debugger.debug(Flag.LAPLACIAN, () => {
      GLOBAL_TIMER.start("HardConstraintsDeformation.precompute()");
    });
    super.precompute(L, free, handle);
    const L1 = L.subset(index(free, free));
    const L2 = L.subset(index(handle, free));
    const A = L1;
    const b = multiply(L2, -1).toArray();
    this.#x = solve(A, b);
    Debugger.debug(Flag.LAPLACIAN, () => {
      GLOBAL_TIMER.step("HardConstraintsDeformation.precompute()");
    });
  }
  // update (vertices) {
  //   // the update is rather fast so no useful information from timing this function
  //   Debugger.debug(Flag.LAPLACIAN, () => {
  //     GLOBAL_TIMER.start('HardConstraintsDeformation.update()')
  //   })
  //
  //   if (!super.update(vertices))
  //     return false
  //
  //   Debugger.debug(Flag.LAPLACIAN, () => {
  //     GLOBAL_TIMER.step('HardConstraintsDeformation.update()')
  //   })
  //   return true
  // }
  deform(vertices) {
    Debugger.debug(Flag.LAPLACIAN, () => {
      GLOBAL_TIMER.start("HardConstraintsDeformation.deform()");
    });
    if (!super.deform(vertices))
      return false;
    const fl = this._free.length;
    const hl = this._handle.length;
    for (let f = 0; f < fl; f++) {
      this.#d.set(0, 0, 0);
      for (let h = 0; h < hl; h++) {
        const b = this.#x[h][f];
        const hi = this._handle[h];
        const vh = vertices[this._handle[h]].position;
        const dhx = vh.x - this._p[0][hi];
        const dhy = vh.y - this._p[1][hi];
        const dhz = vh.z - this._p[2][hi];
        this.#d.x += b * dhx;
        this.#d.y += b * dhy;
        this.#d.z += b * dhz;
      }
      vertices[this._free[f]].position.add(this.#d);
    }
    Debugger.debug(Flag.LAPLACIAN, () => {
      GLOBAL_TIMER.step("HardConstraintsDeformation.deform()");
    });
    return true;
  }
};

