// src/simulation/tools/shadow_removal/ShadowCleaningRenderer.js
var ShadowCleaningRenderer = class {
  // attributes
  /** @type {RenderTextureScene} */
  #renderer;
  /** @type {SimulationTypeValue} */
  #simulationType;
  /** @type {?ShadowCleaningMaterial} */
  #shadowCleaningMaterial = null;
  /** @type {?VertexMaskMaterial} */
  #vertexMaskMaterial = null;
  /** @type {WebGLRenderTarget} */
  #renderTarget = null;
  /** @type {?Texture} */
  #cleanMap = null;
  /** @type {?Map<MorphTarget, Texture>} */
  #ambientMaps = null;
  // memory optimization
  #clearColor = new Color(0, 0, 0);
  // flags
  #initialized = false;
  /**
   * Creates a {@link ShadowCleaningRenderer}.
   * @param {object} parameters Constructor parameters.
   * @param {RenderTextureScene} parameters.renderer Renderer to use.
   * @param {SimulationTypeValue} parameters.simulationType Simulation type to render for.
   */
  constructor(parameters) {
    checkTypes([parameters.renderer, parameters.simulationType], [RenderTextureScene, "symbol"]);
    this.#renderer = parameters.renderer;
    this.#simulationType = parameters.simulationType;
  }
  /**
   * Returns the shadowless texture map of the shadow cleaning material.
   * @returns {Texture}
   */
  get cleanMap() {
    return this.#cleanMap;
  }
  /**
   * Updates the shadowless texture map of the shadow cleaning material.
   * @param {Texture} texture
   */
  set cleanMap(texture) {
    this.#cleanMap = texture;
  }
  /**
   * Returns the ambient occlusion maps of the shadow cleaning material.
   * @returns {?Map<MorphTarget, Texture>}
   */
  get ambientMaps() {
    return this.#ambientMaps;
  }
  /**
   * Updates the ambient occlusion maps of the shadow cleaning material.
   * @param {?Map<MorphTarget, Texture>} maps
   */
  set ambientMaps(maps) {
    this.#ambientMaps = maps;
  }
  /**
   * Lazily instantiates the required elements to render a shadow cleaning texture.
   */
  #initialize() {
    if (this.#initialized)
      return;
    this.#shadowCleaningMaterial = new ShadowCleaningMaterial();
    this.#vertexMaskMaterial = new VertexMaskMaterial({ simulationType: this.#simulationType, uvSet: UnwrapUvSet.UV1 });
    this.#renderTarget = new WebGLRenderTarget(BASE_TEXTURE_SIZE, BASE_TEXTURE_SIZE);
    this.#initialized = true;
  }
  /**
   * Renders a shadow cleaning texture.
   * @param {ShadowCleaning} shadowCleaning Shadow cleaning to render.
   */
  render(shadowCleaning) {
    this.#initialize();
    let maxIntensity = 0;
    let maxMorphTarget = null;
    for (const element of shadowCleaning.intensities) {
      if (!this.#ambientMaps?.has(element.morphTarget))
        continue;
      if (element.intensity > maxIntensity) {
        maxIntensity = element.intensity;
        maxMorphTarget = element.morphTarget;
      }
    }
    if (!maxMorphTarget)
      return;
    this.#shadowCleaningMaterial.aoMap = this.#ambientMaps.get(maxMorphTarget);
    shadowCleaning.setMask(maxMorphTarget);
    const model = shadowCleaning.model;
    model.setAttribute(VERTEX_MASK_ATTRIBUTE, shadowCleaning.maskAttribute);
    model.replaceMaterial(this.#vertexMaskMaterial.material);
    this.#renderer.render(this.#renderTarget, model.mesh);
    model.restoreMaterial();
    blur(this.#renderer, this.#renderTarget, SHADOW_CLEANING_BLUR_AMOUNT, SHADOW_CLEANING_BLUR_AMOUNT);
    this.#shadowCleaningMaterial.map = model.sharpenTextureMap ? model.sharpenTextureMap : model.skinTextureMap;
    this.#shadowCleaningMaterial.cleanMap = this.#cleanMap;
    this.#shadowCleaningMaterial.mask = this.#renderTarget.texture;
    this.#shadowCleaningMaterial.intensity = getIntensity(maxMorphTarget.type, maxIntensity);
    this.#renderer.updateMaterial(this.#shadowCleaningMaterial.material);
    this.#renderer.render(shadowCleaning.renderTarget);
    model.deleteAttribute(VERTEX_MASK_ATTRIBUTE);
  }
  /**
   * Clears the shadow cleaning texture.
   * @param {ShadowCleaning} shadowCleaning Shadow cleaning to clear.
   */
  clear(shadowCleaning) {
    this.#initialize();
    this.#renderer.clearRenderTarget(shadowCleaning.renderTarget, this.#clearColor, 0);
  }
};

// src/simulation/tools/shadow_removal/ShadowCleaningTool.js
var ShadowCleaningTool = class extends Tool {
  // attributes
  /** @type {Model} */
  #beforeModel;
  /** @type {Texture} */
  #cleanMap = null;
  /** @type {ShadowCleaningRenderer} */
  #renderer;
  /** @type {MorphTargets} */
  #morphTargets = null;
  /** @type {?Model} */
  #lastAppliedModel = null;
  /** @type {?MorphTarget} */
  #lastAppliedMorphTarget = null;
  #lastAppliedIntensity = 0;
  // per model information
  /** @type {Map<Model, ShadowCleaning>} */
  #shadowCleanings = /* @__PURE__ */ new Map();
  /** @type {Map<MorphTarget, Texture>} */
  #morphTargetAmbientMaps = /* @__PURE__ */ new Map();
  /**
   * Creates a {@link ShadowCleaningTool}.
   * @param {object} parameters Constructor parameters.
   * @param {RenderTextureScene} parameters.renderer Renderer to use.
   * @param {Model} parameters.beforeModel Original simulation model.
   */
  constructor(parameters) {
    super({ id: SHADOW_CLEANING_TOOL_ID, editType: ToolEditType.NONE, exportName: SHADOW_CLEANING_TOOL_EXPORT_NAME });
    checkTypes([parameters.renderer, parameters.beforeModel], [RenderTextureScene, Model]);
    this.#beforeModel = parameters.beforeModel;
    this.#renderer = new ShadowCleaningRenderer({ renderer: parameters.renderer, simulationType: parameters.beforeModel.type });
    this.#renderer.cleanMap = this.#beforeModel.sharpenTextureMap ? this.#beforeModel.sharpenTextureMap : this.#beforeModel.skinTextureMap;
    this.toggle(false);
  }
  /**
   * Sets the morph targets.
   * @param {MorphTargets} morphTargets Object containing all the morph targets.
   */
  setMorphTargets(morphTargets) {
    this.#morphTargets = morphTargets;
  }
  /**
   * @inheritdoc
   * @type {Tool['onCreateModel']}
   * @returns
   */
  onCreateModel(model, sourceModel = null, editable = true) {
    if (!this._enabled)
      return;
    if (sourceModel === null)
      return;
    if (this.#shadowCleanings.has(model)) {
      return;
    }
    if (!this.#shadowCleanings.has(sourceModel))
      return;
    const clone6 = this.#shadowCleanings.get(sourceModel).clone(model);
    if (clone6.enabled)
      this.#renderer.render(clone6);
    this.#shadowCleanings.set(model, clone6);
  }
  /**
   * Returns the {@link ShadowCleaning} of a parameter model.
   * @param {Model} model Target model.
   * @returns {ShadowCleaning}
   */
  #getShadowCleaning(model) {
    const hasModel = this.#shadowCleanings.has(model);
    const cleanMap = this.#renderer.cleanMap;
    const shadowCleaning = hasModel ? this.#shadowCleanings.get(model) : new ShadowCleaning({ model, width: cleanMap.width, height: cleanMap.height });
    if (!hasModel) {
      shadowCleaning.enabled = true;
      this.#shadowCleanings.set(model, shadowCleaning);
    }
    return shadowCleaning;
  }
  /**
   * Loads the shadow cleaning maps used in morph target deformation.
   * @param {object} parameters Map parameters.
   * @param {string} [parameters.cleanMapUrl] Optional shadowless clean map URL.
   * @param {Array<{ areaName: string, modelName: string, deformationName: string, url: string }>} parameters.ambientMaps Ambient occlusion map URLs per morph target.
   */
  async loadShadowCleaningMaps(parameters) {
    if (parameters.cleanMapUrl) {
      this.#cleanMap?.dispose();
      this.#cleanMap = await loadTexture(parameters.cleanMapUrl);
      this.#renderer.cleanMap = this.#cleanMap;
    }
    const results = await Promise.all(
      parameters.ambientMaps.map(async (ambient) => {
        const texture = await loadTexture(ambient.url);
        const morphTarget = getMorphTarget(this.#morphTargets, ambient.areaName, ambient.modelName, ambient.deformationName);
        return { morphTarget, texture };
      })
    );
    if (results.length > 0)
      this.toggle(true);
    results.forEach(({ morphTarget, texture }) => {
      this.#morphTargetAmbientMaps.get(morphTarget)?.dispose();
      this.#morphTargetAmbientMaps.set(morphTarget, texture);
    });
    this.#renderer.ambientMaps = this.#morphTargetAmbientMaps;
    if (this._enabled) {
      for (const shadowCleaning of this.#shadowCleanings.values()) {
        shadowCleaning.enabled = true;
        this.#renderer.render(shadowCleaning);
      }
    }
  }
  /**
   * Toggles the shadow cleaning tool for a parameter model.
   * @param {Model} model Target model.
   * @param {boolean} enable Whether to enable or disable the shadow cleaning.
   * @returns {boolean} Whether the shadow cleaning was toggled.
   */
  toggleShadowCleaning(model, enable) {
    if (!this._enabled)
      return false;
    if (model === this.#beforeModel)
      return false;
    const shadowCleaning = this.#getShadowCleaning(model);
    shadowCleaning.enabled = enable;
    return true;
  }
  /**
   * Applies a shadow cleaning operation to a target morph target deformation with a given intensity.
   * It saves all the currently applied morph targets and apply them all at the same time each call.
   * @param {Model} model Current simulation model.
   * @param {object} parameters Tool parameters.
   * @param {string} parameters.areaName The morph target area name identifier.
   * @param {string} parameters.modelName The morph target model name identifier.
   * @param {string} parameters.deformationName The morph target deformation name identifier.
   * @param {number} parameters.intensity The morph target deformation intensity.
   * @override
   */
  action(model, parameters = {}) {
    checkTypes(
      [
        model,
        parameters.areaName,
        parameters.modelName,
        parameters.deformationName,
        parameters.intensity
      ],
      [Model, "string", "string", "string", "number"]
    );
    const morphTarget = getMorphTarget(this.#morphTargets, parameters.areaName, parameters.modelName, parameters.deformationName);
    const shadowCleaning = this.#getShadowCleaning(model);
    if (morphTarget.type === MorphTargetType.NONE) {
      if (shadowCleaning.enabled) {
        this.#renderer.render(shadowCleaning);
      }
      return;
    }
    if (model === this.#lastAppliedModel && morphTarget === this.#lastAppliedMorphTarget && parameters.intensity === this.#lastAppliedIntensity) {
      return;
    }
    this.#lastAppliedModel = model;
    this.#lastAppliedMorphTarget = morphTarget;
    this.#lastAppliedIntensity = parameters.intensity;
    shadowCleaning.setMorphTargetIntensity(morphTarget, parameters.intensity);
    if (shadowCleaning.enabled)
      this.#renderer.render(shadowCleaning);
  }
  /**
   * @inheritdoc
   * @type {Tool['reset']}
   */
  reset(model) {
    if (this.#shadowCleanings.has(model)) {
      const shadowCleaning = this.#shadowCleanings.get(model);
      shadowCleaning.reset();
      this.#renderer.clear(shadowCleaning);
    }
  }
  /**
   * @inheritdoc
   * @type {Tool['disposeElements']}
   */
  disposeElements(model) {
    if (this.#shadowCleanings.has(model)) {
      const shadowCleaning = this.#shadowCleanings.get(model);
      this.#shadowCleanings.delete(model);
      shadowCleaning.dispose();
    }
  }
  /**
   * Exports the shadow cleaning of a given {@link model}.
   * @param {Model} model The target model.
   * @returns {?string} String containing the shadow cleaning JSON or null if no shadow cleaning was applied
   */
  exportToJSON(model) {
    if (!this.#shadowCleanings.has(model))
      return null;
    const shadowCleaning = this.#shadowCleanings.get(model);
    return JSON.stringify(shadowCleaning.exportToJSON());
  }
  /**
   * Imports the shadow cleaning for a given {@link model}.
   * @param {Model} model The target model.
   * @param {ShadowCleaningData} data Shadow cleaning JSON object.
   */
  importFromJSON(model, data) {
    const shadowCleaning = this.#getShadowCleaning(model);
    shadowCleaning.importFromJSON(this.#morphTargets, data);
    if (shadowCleaning.enabled)
      this.#renderer.render(shadowCleaning);
  }
  /**
   * @override
   * Exports tool data as an object for a parameter model.
   * @param {Model} model The model.
   * @returns {?ShadowCleaningData}
   */
  export(model) {
    if (!this._enabled) super.export(model);
    return this.#shadowCleanings.has(model) ? this.#shadowCleanings.get(model).exportToJSON() : null;
  }
  /**
   * @override
   * Imports the tool data for a requested model.
   * @param {Model} model Requested model.
   * @param {ShadowCleaningData} parameters Array containing the import data.
   */
  import(model, parameters) {
    const shadowCleaning = this.#getShadowCleaning(model);
    shadowCleaning.importFromJSON(this.#morphTargets, parameters);
  }
};

