  /**
   * Loads asynchronously a k3d and texture and attaches it to the parameter viewport.
   * If the parameter viewport already has a simulation, the simulation is removed.
   * When done, the selected viewport is enabled and rendered.
   * If the maximum amount of simulations is reached (5) an error is thrown.
   * The created simulation will not be editable.
   * @param {string} viewportId Viewport identifier where the simulation should be created.
   * @param {object} parameters Object containing the URLs for both k3d and texture.
   * @param {string} parameters.meshUrl URL containing the path to the k3d file.
   * @param {string} [parameters.alphaMapUrl] Optional URL containing the path to the full-scan alpha map texture file.
   * @param {string} parameters.textureUrl URL containing the path to the texture file.
   * @param {string} [parameters.fullScanMeshUrl] Optional URL containing the path to the full-scan k3d file.
   * @param {string} [parameters.fullScanTextureUrl] Optional URL containing the path to the full-scan texture file.
   * @param {string} [parameters.fullScanAlphaMapUrl] Optional URL containing the path to the full-scan alpha map texture file.
   * @param {string} [parameters.scarsUrl] Optional URL containing the path to the scars file (JSON format).
   * @param {string} [parameters.stampsUrl] Optional URL containing the path to the stamps file (JSON format).
   * @param {string} [parameters.drawingsUrl] Optional URL containing the path to the drawings file (JSON format).
   * @param {string} [parameters.texturePaintDrawingsUrl] Optional URL containing the path to the Texture Paint drawings file (JSON format).
   * @param {string} [parameters.imperfectionsVisualJsonUrl] Optional URL containing the path to the skin imperfections visual JSON file.
   * @param {string} [parameters.shadowCleaningUrl] Optional URL containing the path to the shadow cleaning data file (JSON format).
   * @param {string} [parameters.skeletonUrl] Optional URL containing the path to the skeleton .gltf file.
   * @param {string} [parameters.simulationDataUrl] Optional URL containing the path to the .json file containing all simulation saved data.
   * @param {string} [parameters.textureFullBodyHeadUrl] Optional URL containing the path to the full body head texture file.
   * @param {string} [parameters.textureFullBodyHeadAlphaMapUrl] Optional URL containing the path to the full body head alpha map texture file.
   * @param {string} [parameters.textureFullBodyLimbsUrl] Optional URL containing the path to the full body limbs texture file.
   * @param {string} [parameters.textureFullBodyLimbsAlphaMapUrl] Optional URL containing the path to the full body limbs alpha map texture file.
   * @param {SimulationTypeValue} parameters.type The type of the simulation.
   * @returns {Promise} Promise where the simulation will be loaded.
   */
  async loadSimulation(viewportId, parameters) {
    checkTypes([viewportId, parameters], ["string", Object]);
    try {
      if (parameters.simulationDataUrl) {
        if (this.#viewer.isViewportClear(viewportId)) {
          await this.#simulator.cloneSimulation(this.#viewer.beforeViewportId, viewportId);
          const model2 = this.#simulator.getSimulationModel(viewportId);
          this.#viewer.setAfterModel(model2, viewportId);
        }
        await this.importSimulationParameters(viewportId, parameters.simulationDataUrl);
        return;
      }
      if (!this.#viewer.isViewportClear(viewportId)) {
        this.removeSimulation(viewportId);
      }
      parameters.tweener = this.#viewer.tweener;
      const model = await this.#patient.loadModel({ ...parameters, name: viewportId });
      await this.#simulator.createSimulation(viewportId, model, false);
      this.#viewer.setAfterModel(model, viewportId, true);
      if (parameters.scarsUrl)
        await this.#simulator.importSimulationScars(viewportId, parameters.scarsUrl);
      if (parameters.stampsUrl)
        await this.#simulator.importSimulationStamps(viewportId, parameters.stampsUrl);
      if (parameters.drawingsUrl)
        await this.#simulator.importSimulationDrawings(viewportId, parameters.drawingsUrl);
      if (parameters.texturePaintDrawingsUrl)
        await this.#simulator.importSimulationTexturePaintDrawings(viewportId, parameters.texturePaintDrawingsUrl);
      if (parameters.imperfectionsVisualJsonUrl)
        await this.#simulator.loadAfterSkinImperfectionsVisualJson(viewportId, parameters.imperfectionsVisualJsonUrl);
      if (parameters.shadowCleaningUrl)
        await this.#simulator.importSimulationShadowCleaning(viewportId, parameters.shadowCleaningUrl);
      await this.#simulator.onCreateModel(model, null, false);
      this.render();
    } catch (e) {
      Debugger.handle(e);
    }
  }
